const today = $now.toFormat('dd/MM/yyyy');
const prompt = 'Nous sommes le ' + today + '. Tu es un journaliste tech specialise en intelligence artificielle. Utilise la recherche web pour trouver, pour chacune des entreprises suivantes : Google, Apple, OpenAI, Anthropic, Mistral AI, DeepSeek, les 5 actualites les plus recentes et les plus notables concernant l\'intelligence artificielle (nouveaux modeles, produits, annonces, partenariats, recherche). Pour chaque entreprise, regroupe ses actualites sous un intertitre avec le nom exact de l\'entreprise (par exemple \'OpenAI:\'). Pour chaque actualite, ecris un paragraphe separe donnant : le titre de l\'article, le nom du site source, la date de publication si connue, un resume en 1-2 phrases, et cite la page web qui te sert de source pour cette information. Privilegie les actualites des deux dernieres semaines. Verifie via la recherche web que chaque actualite est reelle et recente. N\'invente jamais une actualite ; si tu ne trouves pas assez d\'actualites recentes pour une entreprise, indique-le simplement pour cette entreprise plutot que d\'en inventer.';

const body = {
  model: 'gpt-4.1',
  tools: [{ type: 'web_search' }],
  input: prompt,
};

return [{ json: { body } }];

const response = $input.first().json;
const output = response.output || [];
let text = '';
let annotations = [];
for (const item of output) {
  if (item.type === 'message' && Array.isArray(item.content)) {
    for (const c of item.content) {
      if (c.type === 'output_text') {
        text = c.text || '';
        annotations = c.annotations || [];
      }
    }
  }
}

const sorted = annotations.filter(a => a.type === 'url_citation' && a.url).sort((a, b) => b.end_index - a.end_index);
for (const a of sorted) {
  const insert = ' (Source: ' + a.url + ')';
  text = text.slice(0, a.end_index) + insert + text.slice(a.end_index);
}

return [{ json: { annotated_text: text } }];

const today = $now.toFormat('dd/MM/yyyy');
const prompt = 'Nous sommes le ' + today + '. Utilise la recherche web pour etablir le classement actuel des 10 meilleurs grands modeles de langage (LLM), toutes entreprises confondues (OpenAI, Google, Anthropic, Meta, Mistral AI, DeepSeek, xAI, etc.), en te basant sur des classements/benchmarks publics reconnus (par exemple LMArena / Chatbot Arena, ou des comparatifs recents de la presse tech specialisee). Pour chaque modele du classement, indique dans un paragraphe separe : son rang, son nom exact, l\'entreprise qui l\'a developpe, et une note courte (une phrase) precisant son point fort ou son score si connu. Cite la ou les pages qui te servent de source pour ce classement. Utilise des informations aussi recentes que possible.';

const body = {
  model: 'gpt-4.1',
  tools: [{ type: 'web_search' }],
  input: prompt,
};

return [{ json: { body } }];

