const news = $('Inserer citations actualites').item.json.annotated_text || '';
const ranking = $('Inserer citations classement').item.json.annotated_text || '';
const harness = $('Inserer citations harness').item.json.annotated_text || '';
const combined = '=== ACTUALITES PAR ENTREPRISE ===\n' + news
  + '\n\n=== CLASSEMENT DES MEILLEURS LLM ===\n' + ranking
  + '\n\n=== CLASSEMENT DES MEILLEURS HARNESSES (AGENTS DE CODE) ===\n' + harness;
return [{ json: { combined_text: combined } }];

const text = $input.first().json.combined_text || '';
const prompt = 'Voici un texte en trois parties : des actualites IA regroupees par entreprise (Google, Apple, OpenAI, Anthropic, Mistral AI, DeepSeek), un classement des meilleurs LLM, puis un classement des meilleurs "harnesses"/agents de code (Claude Code, Cursor, etc.). Des mentions "(Source: URL)" indiquent l\'URL de la page web la plus proche pour l\'information qui precede. Extrait ce contenu sous forme structuree selon le schema fourni. Pour chaque actualite, mets-la dans le tableau correspondant a son entreprise (google, apple, openai, anthropic, mistral, deepseek) ; le champ link doit reprendre telle quelle l\'URL "(Source: ...)" la plus proche et la plus pertinente pour cette actualite precise, ou une chaine vide si aucune URL claire n\'y est associee. Pour les deux classements, respecte l\'ordre de rang indique dans le texte ; le champ note ne doit contenir que le point fort/score, jamais de mention "(Source: ...)" ni d\'URL brute (le schema n\'a pas de champ pour la source des classements, donc omets-la simplement). Ne modifie aucun fait et n\'ajoute aucune actualite, aucun modele ni aucun outil qui ne serait pas deja present dans le texte.\n\nTexte:\n' + text;

const newsItemSchema = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    link: { type: 'string' },
    source: { type: 'string' },
    published_at: { type: 'string' },
    summary: { type: 'string' },
  },
  required: ['title', 'link', 'source', 'published_at', 'summary'],
  additionalProperties: false,
};

const body = {
  model: 'gpt-4.1',
  input: prompt,
  text: {
    format: {
      type: 'json_schema',
      name: 'news_ai_digest',
      strict: true,
      schema: {
        type: 'object',
        properties: {
          news: {
            type: 'object',
            properties: {
              google: { type: 'array', items: newsItemSchema },
              apple: { type: 'array', items: newsItemSchema },
              openai: { type: 'array', items: newsItemSchema },
              anthropic: { type: 'array', items: newsItemSchema },
              mistral: { type: 'array', items: newsItemSchema },
              deepseek: { type: 'array', items: newsItemSchema },
            },
            required: ['google', 'apple', 'openai', 'anthropic', 'mistral', 'deepseek'],
            additionalProperties: false,
          },
          ranking: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                rank: { type: 'integer' },
                model: { type: 'string' },
                company: { type: 'string' },
                note: { type: 'string' },
              },
              required: ['rank', 'model', 'company', 'note'],
              additionalProperties: false,
            },
          },
          harness_ranking: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                rank: { type: 'integer' },
                name: { type: 'string' },
                company: { type: 'string' },
                note: { type: 'string' },
              },
              required: ['rank', 'name', 'company', 'note'],
              additionalProperties: false,
            },
          },
        },
        required: ['news', 'ranking', 'harness_ranking'],
        additionalProperties: false,
      },
    },
  },
};

return [{ json: { body } }];

const response = $input.first().json;
let text = '';
const output = response.output || [];
for (const item of output) {
  if (item.type === 'message' && Array.isArray(item.content)) {
    for (const c of item.content) {
      if (c.type === 'output_text' && c.text) text += c.text;
    }
  }
}
if (!text && response.output_text) text = response.output_text;

text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
}

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {};
}

// Same manual-string-parsing link filter as the art-actu newsletter
// workflow's "Extraire JSON expositions" node: the URL constructor isn't
// reliably available in n8n's Code node sandbox, which previously made
// every single link silently fail and get rejected regardless of content.
function isLowValueLink(link) {
  const noFragment = link.split('#')[0];
  const noQuery = noFragment.split('?')[0];
  const afterProtocol = noQuery.replace(/^https?:\/\//i, '');
  const slashIdx = afterProtocol.indexOf('/');
  const path = slashIdx === -1 ? '' : afterProtocol.slice(slashIdx);
  const trimmed = path.replace(/\/+$/, '');
  if (trimmed === '') return true;
  const segments = trimmed.split('/').filter(Boolean);
  const last = (segments[segments.length - 1] || '').toLowerCase();
  const generic = ['recherche','search','agenda','actualites','actualite','news','accueil','home','index','blog','blogs'];
  if (generic.includes(last)) return true;
  if (segments.length === 1 && /^[a-z]{2}$/.test(last)) return true;
  return false;
}

// OpenAI's web_search tool appends its own "?utm_source=openai" tracking
// param to every citation URL — drop utm_* params before storing/showing
// the link, they're noise for our readers and not something worth
// telling the destination site.
function stripUtmParams(link) {
  const [base, query] = link.split('?');
  if (!query) return link;
  const kept = query.split('&').filter(p => !/^utm_/i.test(p));
  return kept.length ? base + '?' + kept.join('&') : base;
}

function cleanNewsList(list) {
  if (!Array.isArray(list)) return [];
  const seenUrls = new Set();
  return list
    .filter(it => it && it.title && typeof it.link === 'string' && /^https?:\/\//i.test(it.link) && !isLowValueLink(it.link))
    .map(it => ({ ...it, link: stripUtmParams(it.link) }))
    .filter(it => {
      if (seenUrls.has(it.link)) return false;
      seenUrls.add(it.link);
      return true;
    })
    .slice(0, 5)
    .map(it => ({
      title: String(it.title),
      url: String(it.link),
      source: String(it.source || ''),
      published_at: String(it.published_at || ''),
      summary: String(it.summary || ''),
    }));
}

const newsRaw = (parsed && parsed.news) || {};
const news = {
  google: cleanNewsList(newsRaw.google),
  apple: cleanNewsList(newsRaw.apple),
  openai: cleanNewsList(newsRaw.openai),
  anthropic: cleanNewsList(newsRaw.anthropic),
  mistral: cleanNewsList(newsRaw.mistral),
  deepseek: cleanNewsList(newsRaw.deepseek),
};

// The ranking schema has no dedicated source-link field, but the model
// sometimes embeds the raw "(Source: URL)" citation marker straight into
// the note text anyway — strip it rather than relying on the prompt alone
// to keep the model from doing that.
function stripSourceMarkers(text) {
  return text.replace(/\s*\(?Source\s*:\s*https?:\/\/\S+\)?/gi, '').trim();
}

const rankingRaw = Array.isArray(parsed.ranking) ? parsed.ranking : [];
const ranking = rankingRaw
  .filter(r => r && r.model)
  .map(r => ({
    rank: Number(r.rank) || 0,
    model: String(r.model),
    company: String(r.company || ''),
    note: stripSourceMarkers(String(r.note || '')),
  }))
  .sort((a, b) => a.rank - b.rank)
  .slice(0, 10);

const harnessRankingRaw = Array.isArray(parsed.harness_ranking) ? parsed.harness_ranking : [];
const harness_ranking = harnessRankingRaw
  .filter(r => r && r.name)
  .map(r => ({
    rank: Number(r.rank) || 0,
    name: String(r.name),
    company: String(r.company || ''),
    note: stripSourceMarkers(String(r.note || '')),
  }))
  .sort((a, b) => a.rank - b.rank)
  .slice(0, 10);

return [{ json: { news, ranking, harness_ranking } }];

const newsData = $('Extraire JSON news').item.json;
const today = $now.toFormat('yyyy-MM-dd');

// Yahoo Finance's public chart endpoint needs no API key/signup — same
// "no keys to manage" preference as Nominatim/OSM elsewhere on this site.
function parseYahoo(resp) {
  try {
    const meta = resp.chart.result[0].meta;
    if (typeof meta.regularMarketPrice !== 'number') return null;
    return {
      price: meta.regularMarketPrice,
      currency: meta.currency || 'USD',
      change_percent: typeof meta.regularMarketChangePercent === 'number' ? meta.regularMarketChangePercent : null,
      as_of: today,
    };
  } catch (e) {
    return null;
  }
}

const googleStock = parseYahoo($('Recuperer cours Google').item.json);
const appleStock = parseYahoo($('Recuperer cours Apple').item.json);

const stocks = {};
if (googleStock) stocks.google = googleStock;
if (appleStock) stocks.apple = appleStock;

const payload = {
  date: today,
  news: newsData.news,
  ranking: newsData.ranking,
  harness_ranking: newsData.harness_ranking,
  stocks: stocks,
};

return [{ json: { payload } }];

